class A { public static int X = B.Y + 1; }
class B { public static int Y = A.X + 1; }
class Singleton {
 public static readonly Singleton Instance = new Singleton();
 public static readonly string Name = "Ada";
 public int N;
 private Singleton() { Print("instance"); N = 4; }
 static Singleton() { Print("static"); }
}
void Main() {
 Print(A.X); Print(B.Y); Print(Singleton.Instance.N);
 Print(Singleton.Instance == Singleton.Instance); Print(Singleton.Name);
}
